const visual = {
  prepare: function (input) {
    return [{ kind: 'text', payload: '4:1' }];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var x1 = Math.max(24, w * 0.12);
    var x2 = Math.min(w - 24, w * 0.88);
    if (x2 <= x1) { x1 = 12; x2 = w - 12; }
    var y = h * 0.55;
    var divX = x1 + (x2 - x1) * 4 / 5;
    var tick = Math.max(6, Math.min(12, h * 0.04));
    var labelX = (x1 + x2) / 2;
    var labelY = y - tick - Math.max(16, h * 0.05);
    if (labelY < 18) { labelY = y + tick + Math.max(18, h * 0.05); }
    labelY = Math.min(h - 12, Math.max(18, labelY));
    var segment = visualSdk.polyline([[x1, y], [x2, y]]);
    var divider = visualSdk.polyline([[divX, y - tick], [divX, y + tick]]);
    return {
      schemaVersion: 1,
      sceneId: 'ratio-segment',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'segment', commands: segment },
        { id: 'divider', commands: divider }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'segment', stroke: '#1f2937', strokeWidth: 3, fill: 'none' },
          { type: 'path', pathId: 'divider', stroke: '#1f2937', strokeWidth: 3, fill: 'none' },
          { type: 'label', text: '4:1', x: labelX, y: labelY, fontSize: 18, fill: '#111827', textAnchor: 'middle' }
        ]
      }
    };
  }
};
